import { ApolloClient, InMemoryCache, createHttpLink, ApolloLink, from } from '@apollo/client';
import { onError } from '@apollo/client/link/error';
import { setContext } from '@apollo/client/link/context';
import { refreshToken } from './services/auth';

// HTTP connection to the API
const httpLink = createHttpLink({
  uri: 'http://localhost:8000/graphql',
  credentials: 'include', // This will include cookies with the request
});

// Middleware to add auth token to headers
const authLink = setContext((_, { headers }) => {
  // Get the authentication token from local storage if it exists
  const token = localStorage.getItem('access_token');

  // Return the headers to the context so httpLink can read them
  return {
    headers: {
      ...headers,
      authorization: token ? `Bearer ${token}` : '',
    }
  };
});

// Error handling for authentication
const errorLink = onError(({ graphQLErrors, networkError, operation, forward }) => {
  if (graphQLErrors) {
    for (let err of graphQLErrors) {
      console.error('GraphQL Error:', err);

      // Handle token expiration
      if (err.extensions?.code === 'UNAUTHENTICATED' || 
          err.message.includes('Not authenticated')) {

        // Try to refresh the token
        const refreshTokenValue = localStorage.getItem('refresh_token');
        if (refreshTokenValue) {
          return refreshToken().then(({ access_token }) => {
            if (!access_token) {
              // If refresh failed, clear tokens and redirect to login
              localStorage.removeItem('access_token');
              localStorage.removeItem('refresh_token');
              window.location.href = '/login';
              return;
            }

            // Update the authorization header with the new token
            const oldHeaders = operation.getContext().headers;
            operation.setContext({
              headers: {
                ...oldHeaders,
                authorization: `Bearer ${access_token}`,
              },
            });

            // Retry the request with the new token
            return forward(operation);
          });
        } else {
          // No refresh token, redirect to login
          localStorage.removeItem('access_token');
          window.location.href = '/login';
        }
      }
    }
  }

  if (networkError) {
    console.error(`[Network error]: ${networkError}`);

    // Handle 401 Unauthorized
    if (networkError.statusCode === 401) {
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      window.location.href = '/login';
    }
  }
});

// Create the Apollo Client instance with cache configuration
const client = new ApolloClient({
  link: from([
    errorLink,
    authLink,
    httpLink,
  ]),
  cache: new InMemoryCache({
    typePolicies: {
      Query: {
        fields: {
          // Add any specific field policies here if needed
        },
      },
    },
  }),
  defaultOptions: {
    watchQuery: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    query: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    mutate: {
      errorPolicy: 'all',
    },
  },
});

// Export the client
export default client;
